// Normaliza o payload do WordPress e gera um item por grupo.
// Aceita "jids" (nome atual) e "grupos_jids" (nome antigo) para nao quebrar
// caso o plugin ainda envie o payload legado: era isso que estourava
// "Cannot read properties of undefined (reading 'map')" e virava 500 no WP.
const body = $('Webhook1').first().json.body || {};

const rodizio_id = body.rodizio_id ?? body.cliente_id ?? null;
const instance_name = body.instance_name || '';

// O token pode vir do WordPress ou da linha da instancia no Supabase.
let tokenSupabase = '';
try {
  tokenSupabase = ($('buscar_inst').first().json || {}).token || '';
} catch (e) {
  tokenSupabase = '';
}
const token = body.token || tokenSupabase || '';

const brutos = body.jids || body.grupos_jids || body.groups || [];
const jids = (Array.isArray(brutos) ? brutos : [brutos])
  .map((j) => (typeof j === 'string' ? j : (j && (j.jid || j.JID)) || ''))
  .map((j) => String(j).trim())
  .filter(Boolean);

const erros = [];
if (!rodizio_id) erros.push('rodizio_id ausente no payload');
if (!instance_name) erros.push('instance_name ausente no payload');
if (!token) erros.push('token nao encontrado (nem no payload do WordPress, nem na instancia "' + instance_name + '" no Supabase)');
if (jids.length === 0) erros.push('nenhum grupo recebido em jids/grupos_jids');

// Um item de erro vai direto para a resposta. Devolver 200 com o motivo e
// melhor do que deixar a execucao morrer e o WordPress mostrar "Codigo: 500".
if (erros.length > 0) {
  return [{ json: { _ok: false, erro: erros.join('; '), rodizio_id, instance_name, total: jids.length } }];
}

return jids.map((jid) => ({
  json: {
    _ok: true,
    rodizio_id,
    instance_name,
    token,
    whatsapp_group_id: jid,
  },
}));

// Payload invalido: responde 200 com o motivo em vez de deixar o webhook
// terminar sem Respond (o que faz o n8n devolver 500 ao WordPress).
const j = $json || {};
return [{ json: { sucesso: false, erro: j.erro || 'payload invalido', total: 0, gravados: 0, pulados: 0, grupos: [], ignorados: [] } }];

// Le a resposta da UAZAPI do proprio item ($json) em vez de $item("0").$node[...]:
// dentro do loop a resolucao de paired item quebra e derruba a execucao inteira.
const info = $json || {};
const origem = $('Loop Over Items').first().json || {};

const inviteLink = info.invite_link || info.inviteLink || '';
const whatsapp_group_id = info.JID || origem.whatsapp_group_id || '';
const nome_grupo = info.Name || '';
const participants = info.Participants;
const total_participantes = Array.isArray(participants) ? participants.length : 0;

// wp_rfa_grupos tem NOT NULL em rodizio_id, whatsapp_group_id, nome_grupo e
// link_convite. Sem essa guarda, um grupo sem dados derruba a execucao com
// "Column 'x' cannot be null" e os grupos seguintes nem chegam a ser gravados.
const _gravar = Boolean(inviteLink) && Boolean(whatsapp_group_id) && Boolean(origem.rodizio_id);

if (!_gravar) {
  console.log('[rodizio] grupo PULADO:', JSON.stringify({
    jid: whatsapp_group_id || null,
    tem_invite_link: Boolean(inviteLink),
    erro_uazapi: info.error || info.message || null,
  }));
}

return [{
  json: {
    rodizio_id: origem.rodizio_id,
    whatsapp_group_id: whatsapp_group_id,
    nome_grupo: nome_grupo || whatsapp_group_id || 'sem nome',
    link_grupo: inviteLink,
    status: 'ativo',
    participantes_atuais: total_participantes,
    motivo: _gravar ? null : (info.error || info.message || 'UAZAPI nao devolveu link de convite'),
    _gravar: _gravar,
  },
}];

// O node MySQL substitui o json pelo resultado da query, entao remonta os
// dados do grupo para que o resumo final consiga listar o que foi gravado.
const dados = $('PrepararDados').first().json || {};
const db = $json || {};
const erroDb = db.error || db.message || null;

return [{ json: { ...dados, gravado: !erroDb, motivo: erroDb || dados.motivo || null } }];

// Branch "done" do loop: monta uma resposta unica e previsivel para o WordPress.
const items = $input.all().map((i) => i.json || {});
const gravados = items.filter((i) => i.gravado === true);
const pulados = items.filter((i) => i.gravado !== true);

return [{
  json: {
    sucesso: gravados.length > 0,
    total: items.length,
    gravados: gravados.length,
    pulados: pulados.length,
    grupos: gravados.map((g) => ({
      whatsapp_group_id: g.whatsapp_group_id,
      nome_grupo: g.nome_grupo,
      link_convite: g.link_grupo,
      participantes_atuais: g.participantes_atuais,
    })),
    ignorados: pulados.map((g) => ({
      whatsapp_group_id: g.whatsapp_group_id,
      motivo: g.motivo || 'grupo sem link de convite',
    })),
  },
}];
